  "No refund for an exchange. Completing it sends the same items again from the order's warehouse and takes the returned ones back into stock (not when they are damaged).": "لا استرداد في حالة الاستبدال. إكماله يرسل الأصناف نفسها مجددًا من مستودع الطلب ويعيد الأصناف المرتجعة إلى المخزون (إلا إذا كانت تالفة).",
  "Select a quotation on the Quotation tab to load its items here. Items are inherited from the quotation and cannot be swapped out — change the quotation instead.": "اختر عرض سعر من تبويب عرض السعر لتحميل بنوده هنا. البنود مأخوذة من عرض السعر ولا يمكن استبدالها — عدّل عرض السعر بدلًا من ذلك.",
  "Unit Price (from quotation)": "سعر الوحدة (من عرض السعر)",
  "Items are inherited from the selected quotation. To change which products appear on this order, change the quotation — not the rows below.": "البنود مأخوذة من عرض السعر المختار. لتغيير المنتجات في هذا الطلب، عدّل عرض السعر — لا الأسطر أدناه.",
  "Order totals (summed from all items above)": "إجماليات الطلب (مجموع كل البنود أعلاه)",
  "The opening balance is posted against opening balance equity on the opening date (an overdraft as a negative amount). Reconciliation starts on that date. Linking an account that already has postings? Leave the balance at 0.": "يُرحَّل الرصيد الافتتاحي مقابل حقوق ملكية الرصيد الافتتاحي في تاريخ الافتتاح (السحب على المكشوف كمبلغ سالب). تبدأ التسوية من ذلك التاريخ. هل تربط حسابًا له ترحيلات بالفعل؟ اترك الرصيد 0.",
  "Active (closed accounts can't take new receipts or payments)": "نشط (الحسابات المغلقة لا تقبل مقبوضات أو مدفوعات جديدة)",
  "Goods returned to vendors (from Purchase Returns) and corrections raised on a bill. They reduce what is owed, like payments.": "بضائع أُرجعت للموردين (من مرتجعات المشتريات) وتصحيحات على فاتورة. تخفض المبلغ المستحق مثل المدفوعات.",

