  "Paid Amount and Balance Amount follow this setting automatically. True partial payments would need a real payment-status field from backend rather than a strict yes/no flag.": "يتبع المبلغ المدفوع والرصيد المتبقي هذا الإعداد تلقائيًا. الدفعات الجزئية الفعلية تتطلب حقل حالة دفع من الخادم بدلًا من خيار نعم/لا.",
  "Both addresses belong to the customer — Billing is where the invoice is addressed, Shipping is where goods/services are delivered. Neither is your company's own address.": "العنوانان للعميل — الفوترة هو العنوان الموجهة إليه الفاتورة، والشحن هو مكان تسليم البضائع/الخدمات. لا يمثل أي منهما عنوان شركتك.",
