  "See the steps below; run it again with a new OTP.": "راجع الخطوات أدناه؛ أعد المحاولة برمز تحقق جديد.",
  "Onboarding failed": "فشل الربط",
  "For VAT-registered companies in Saudi Arabia, every issued invoice and credit note becomes a ZATCA e-invoice (XML) with its place in the invoice chain. With a certificate it is also signed and gets the ZATCA QR code, which the invoice PDF prints.": "للشركات المسجلة في ضريبة القيمة المضافة في السعودية، تتحول كل فاتورة وإشعار دائن صادر إلى فاتورة إلكترونية (XML) لدى زاتكا بموقعها في سلسلة الفواتير. ومع وجود شهادة تُوقّع أيضًا وتحصل على رمز QR الخاص بزاتكا الذي يُطبع في ملف PDF للفاتورة.",
  "Signing certificate": "شهادة التوقيع",
  Certificate: "الشهادة",
  "None yet: issued invoices are not signed": "لا توجد بعد: الفواتير الصادرة غير موقّعة",
  "ZATCA connection": "الاتصال بزاتكا",
  "Mock (local, nothing is sent to ZATCA)": "محاكاة (محلية، لا يُرسل شيء إلى زاتكا)",
  "Issued to": "صادرة إلى",
  "Issued by": "صادرة من",
  Environment: "البيئة",
  Expires: "تنتهي في",
  "The zatca.secret setting is missing on the invoice service; certificates can't be stored until it is set.": "إعداد zatca.secret غير موجود في خدمة الفواتير؛ لا يمكن حفظ الشهادات حتى يُضبط.",
  "Create a local test certificate": "إنشاء شهادة اختبار محلية",
  "Onboard with ZATCA": "الربط مع زاتكا",
  "Get an OTP for a new e-invoicing unit in the Fatoora portal, then enter it here. The system makes a key and certificate request, gets the compliance certificate, passes ZATCA's sample checks and receives the production certificate.": "احصل على رمز تحقق لوحدة فوترة إلكترونية جديدة من بوابة فاتورة، ثم أدخله هنا. ينشئ النظام مفتاحًا وطلب شهادة، ويحصل على شهادة الامتثال، ويجتاز فحوصات العينات لدى زاتكا، ثم يستلم شهادة الإنتاج.",
  "OTP from the Fatoora portal": "رمز التحقق من بوابة فاتورة",
