  "Not cleared yet: don't give this invoice to the buyer until ZATCA clears it. It is sent again automatically.": "لم تُعتمد بعد: لا تسلّم هذه الفاتورة للمشتري حتى تعتمدها زاتكا. ستُرسل مجددًا تلقائيًا.",
  "Not reported yet; it is sent again automatically (ZATCA expects it within 24 hours).": "لم يُبلّغ عنها بعد؛ ستُرسل مجددًا تلقائيًا (تتوقعها زاتكا خلال 24 ساعة).",
